const body = $input.item.json.body || $input.item.json;
const action = body.action;
const event  = body.event;
const gcalScope = body.gcal_scope || null; // 'this_only' | 'this_and_following' | 'all' | null

if (!event || !action) return [{ json: { skip: true } }];

const startMs = event.start_at ? new Date(event.start_at).getTime() : null;
const endMs   = event.end_at   ? new Date(event.end_at).getTime()   : null;

const eventColor = event.metadata?.color || event.color || '#3b82f6';

const gcalColorMap = {
  '#3b82f6': '9', '#22c55e': '2', '#a855f7': '3', '#f59e0b': '5',
  '#10b981': '2', '#06b6d4': '7', '#6366f1': '9', '#8b5cf6': '3',
  '#f43f5e': '11', '#6b7280': '8',
};
const gcalColorId = gcalColorMap[eventColor] || '9';

const rawAllDay = event.all_day ?? event.allDay ?? event.metadata?.all_day ?? false;
const allDay = rawAllDay === true || rawAllDay === 'yes' || rawAllDay === 1;

const toSaoPauloLocal = (utcStr) => {
  if (!utcStr) return null;
  const d = new Date(utcStr);
  if (isNaN(d.getTime())) return null;
  const local = new Date(d.getTime() - 3 * 60 * 60 * 1000);
  return local.toISOString().slice(0, 19) + '-03:00';
};

const addOneDay = (dateStr) => {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + 1);
  return d.toISOString().slice(0, 10);
};

const startLocal = toSaoPauloLocal(event.start_at);
const endLocal   = toSaoPauloLocal(event.end_at);
const startDateOnly = startLocal ? startLocal.slice(0, 10) : null;
const endDateOnly   = endLocal   ? addOneDay(endLocal.slice(0, 10)) : null;

// ── Recorrência ───────────────────────────────────────────────────────────────
const recurrence = event.metadata?.recurrence || null;
const rruleRaw   = event.metadata?.rrule || null;
const isRecurrenceChild = event.metadata?.is_recurrence_child === true;

const toRRuleArray = (r) => {
  if (!r) return null;
  if (Array.isArray(r)) return r;
  return [r];
};

const buildRRuleFromRecurrence = (rec, baseStart) => {
  if (!rec) return null;
  const BYDAY = ['SU','MO','TU','WE','TH','FR','SA'];

  const applyEnd = (base) => {
    if (rec.endType === 'count' && rec.endCount > 0) return `${base};COUNT=${rec.endCount}`;
    if (rec.endType === 'date' && rec.endDate) return `${base};UNTIL=${rec.endDate.replace(/-/g,'')}T235959Z`;
    return base;
  };

  if (typeof rec === 'string') {
    if (rec === 'daily')    return ['RRULE:FREQ=DAILY'];
    if (rec === 'weekdays') return ['RRULE:FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR'];
    if (rec.startsWith('weekly_')) return [`RRULE:FREQ=WEEKLY;BYDAY=${BYDAY[new Date(baseStart).getDay()]}`];
    if (rec === 'monthly_weekday') {
      const d = new Date(baseStart);
      const wn = Math.floor((d.getDate() - 1) / 7) + 1;
      return [`RRULE:FREQ=MONTHLY;BYDAY=${wn}${BYDAY[d.getDay()]}`];
    }
    if (rec.startsWith('yearly_')) return ['RRULE:FREQ=YEARLY'];
    return null;
  }

  if (rec.type === 'custom') {
    const freqMap = { daily:'DAILY', weekly:'WEEKLY', monthly:'MONTHLY', yearly:'YEARLY' };
    const freq = freqMap[rec.unit] || 'WEEKLY';
    let base = `RRULE:FREQ=${freq};INTERVAL=${rec.interval || 1}`;
    if ((rec.unit === 'weekly' || rec.unit === 'week') && rec.weekDays?.length > 0) {
      base += `;BYDAY=${rec.weekDays.map(d => BYDAY[d]).join(',')}`;
    }
    return [applyEnd(base)];
  }

  return null;
};

// Para this_only e this_and_following, não envia RRULE (o Google trata a ocorrência individualmente)
const finalRRule = (gcalScope === 'this_only' || gcalScope === 'this_and_following')
  ? null
  : toRRuleArray(rruleRaw) || buildRRuleFromRecurrence(recurrence, event.start_at);

let recurrenceSummary = null;
if (recurrence) {
  if (typeof recurrence === 'string') {
    const labels = { daily: 'Todos os dias', weekdays: 'Dias úteis (seg–sex)', monthly_weekday: 'Mensal (mesmo dia da semana)' };
    if (recurrence.startsWith('weekly_')) recurrenceSummary = 'Semanal';
    else if (recurrence.startsWith('yearly_')) recurrenceSummary = 'Anual';
    else recurrenceSummary = labels[recurrence] || recurrence;
  } else {
    const unitLabels = { daily: 'dia(s)', weekly: 'semana(s)', monthly: 'mês(es)', yearly: 'ano(s)' };
    const endLabel = recurrence.endType === 'count'
      ? ` por ${recurrence.endCount} ocorrência(s)`
      : recurrence.endType === 'date' ? ` até ${recurrence.endDate}` : '';
    recurrenceSummary = `A cada ${recurrence.interval} ${unitLabels[recurrence.unit] || recurrence.unit}${endLabel}`;
  }
}

// ── Participantes ─────────────────────────────────────────────────────────────
const attendees = event.metadata?.attendees || [];
const attendeesGcal = attendees.map(email => typeof email === 'string' ? { email } : email);

// ── gcal_event_id: para this_only usa formato instanceId (baseId_dataUTC) ────
// O Google Calendar identifica ocorrências individuais pelo padrão: baseEventId_YYYYMMDDTHHMMSSZ
const baseGcalId = event.gcal_event_id || event.google_event_id || '';
let instanceGcalId = baseGcalId;
if (gcalScope === 'this_only' && baseGcalId && event.start_at) {
  const instanceDate = new Date(event.start_at)
    .toISOString()
    .replace(/[-:]/g, '')
    .replace('.000Z', 'Z');
  instanceGcalId = `${baseGcalId}_${instanceDate}`;
}

return [{ json: {
  action,
  gcal_scope: gcalScope,
  event_id: event.id,
  title: event.title || '',
  description: event.description || '',
  start_at: event.start_at || null,
  end_at: event.end_at || null,
  start_at_local: startLocal,
  end_at_local: endLocal,
  start_date_only: startDateOnly,
  end_date_only: endDateOnly,
  start_ms: startMs,
  end_ms: endMs,
  location: event.location || '',
  meeting_url: event.meeting_url || '',
  all_day: allDay,
  gcal_event_id: instanceGcalId,
  gcal_base_event_id: baseGcalId,
  color: eventColor,
  gcal_color_id: gcalColorId,
  has_recurrence: !!recurrence,
  is_recurrence_child: isRecurrenceChild,
  rrule_array: finalRRule,
  recurrence_summary: recurrenceSummary,
  recurrence_raw: recurrence,
  attendees: attendees,
  attendees_gcal: attendeesGcal,
  has_attendees: attendees.length > 0
}}];

const prev = $('Parsear Evento').item.json;
const response = $input.item.json;

const gcalEventId = response.id || null;

return [{ json: {
  event_id: prev.event_id,
  gcal_event_id: gcalEventId
}}];

const item = $input.item.json;

const allDay = item.all_day === true || item.all_day === 'yes' || item.all_day === 1;

const description = (item.description || '')
  + (item.meeting_url ? '\n\n🔗 Reunião: ' + item.meeting_url : '')
  + (item.recurrence_summary ? '\n🔁 ' + item.recurrence_summary : '');

const body = allDay
  ? {
      summary: item.title,
      description,
      location: item.location || '',
      colorId: item.gcal_color_id,
      start: { date: item.start_date_only },
      end: { date: item.end_date_only },
      attendees: item.attendees_gcal,
      recurrence: item.rrule_array || []
    }
  : {
      summary: item.title,
      description,
      location: item.location || '',
      colorId: item.gcal_color_id,
      start: { dateTime: item.start_at, timeZone: 'America/Sao_Paulo' },
      end: { dateTime: item.end_at, timeZone: 'America/Sao_Paulo' },
      attendees: item.attendees_gcal,
      recurrence: item.rrule_array || []
    };

return [{ json: { 
  gcal_event_id: item.gcal_event_id,
  all_day_detected: allDay,
  start_date_only: item.start_date_only,
  end_date_only: item.end_date_only,
  start_at: item.start_at,
  body_string: JSON.stringify(body),
  body_parsed: body
}}];

const item = $input.item.json;

const allDay = item.all_day === true || item.all_day === 'yes' || item.all_day === 1;

const description = (item.description || '')
  + (item.meeting_url ? '\n\n🔗 Reunião: ' + item.meeting_url : '')
  + (item.recurrence_summary ? '\n🔁 ' + item.recurrence_summary : '');

const body = allDay
  ? {
      summary: item.title,
      description,
      location: item.location || '',
      colorId: item.gcal_color_id,
      guestsCanSeeOtherGuests: true,
      start: { date: item.start_date_only },
      end: { date: item.end_date_only },
      attendees: item.attendees_gcal,
      recurrence: item.rrule_array || []
    }
  : {
      summary: item.title,
      description,
      location: item.location || '',
      colorId: item.gcal_color_id,
      guestsCanSeeOtherGuests: true,
      start: { dateTime: item.start_at, timeZone: 'America/Sao_Paulo' },
      end: { dateTime: item.end_at, timeZone: 'America/Sao_Paulo' },
      attendees: item.attendees_gcal,
      recurrence: item.rrule_array || []
    };

return [{ json: {
  event_id: item.event_id,
  gcal_event_id: item.gcal_event_id,
  body_string: JSON.stringify(body)
}}];
